  const cab = parts.find((p) => p.id === "cab");
  // windshield (follows the rake, tapers to its measured top width)
  parts.push(...K.assemble.pane({ host: cab, face: "+z", poly: [[-KNOBS.rc_windshield1.v, KNOBS.rc_windshield2.v], [KNOBS.rc_windshield1.v, KNOBS.rc_windshield2.v], [KNOBS.rc_windshield3.v, KNOBS.rc_windshield4.v], [-KNOBS.rc_windshield3.v, KNOBS.rc_windshield4.v]], body: parts, idPrefix: "windshield" }));
