  for (const face of ["+x", "-x"]) parts.push(...K.assemble.pane({ host: cab, face, poly: [[-KNOBS.rc_side1.v, KNOBS.rc_side2.v], [KNOBS.rc_side3.v, KNOBS.rc_side2.v], [KNOBS.rc_side4.v, KNOBS.rc_side5.v], [-KNOBS.rc_side1.v, KNOBS.rc_side5.v]], body: parts, idPrefix: `side_${face[0] === "+" ? "l" : "r"}` }));
  // door handles (inlays, both flanks)
  for (const face of ["+x", "-x"]) parts.push(...K.assemble.handle({ host: cab, face, bounds: K.span({ z: [-KNOBS.rc_door1.v, KNOBS.rc_door2.v], y: [KNOBS.rc_door3.v, KNOBS.rc_door4.v] }), idPrefix: `handle_${face[0] === "+" ? "l" : "r"}` }));
  // door seams (inlay lines, both flanks, relative to the cab)
  for (const face of ["+x", "-x"]) parts.push(...K.assemble.seam({ host: cab, face, body: parts, door: { front: KNOBS.rc_door5.v, rear: KNOBS.rc_door6.v, bottom: KNOBS.rc_door7.v, knee: KNOBS.rc_side2.v, top: KNOBS.rc_door8.v, rake: KNOBS.rc_door9.v }, idPrefix: `door_${face[0] === "+" ? "l" : "r"}` }));
  // headlights (the pair)
  parts.push(...K.assemble.lamp({ body: parts, face: "nose", centre: [KNOBS.rc_headlights1.v, KNOBS.rc_headlights2.v], diameter: KNOBS.rc_headlights3.v, flush: true }));
