  parts.push(...K.assemble.grille({ body: parts, face: "nose", bounds: K.span({ x: [-KNOBS.rc_grille1.v, KNOBS.rc_grille1.v], y: [KNOBS.rc_grille2.v, KNOBS.rc_grille3.v] }), slots: 2 }));
  // mirrors (the pair, at the A-pillar, rounded-rect heads)
